rows=[]
def add(meaning, refs, status='omitted', spans=(), lost='', dim='关系', repair='作为独立全曲读法保留；不强塞到某一S，也不自动当作作品唯一解释。'):
    evidence=[]
    for uid,quote in refs:
        uid='SRC-'+uid
        assert quote in U[uid]['text'],(uid,quote)
        evidence.append(dict(uid=uid,quote=quote))
    for span in spans: assert any(span in b['body'] for b in beads),span
    rows.append(dict(id=f'G-A{len(rows)+1:03}',segment='GLOBAL',meaning=meaning,dimension=dim,distinctive_terms=[],evidence=evidence,status=status,current_spans=list(spans),lost=lost or ('全曲层面的这层意思没有明确表达。' if status=='omitted' else ''),rationale='对照十四段正文整体，局部有相近词语不自动证明全曲关系已被表达。',relation=dict(kind='standalone',with_=[],explanation='全曲读法单列；与局部账本可能重叠，不能简单相加算唯一意义总数。'),repair=repair))

